package net.officefloor.hq.app.person;

import net.officefloor.hq.app.sheet.InvalidSheetRequestException;
import net.officefloor.hq.app.rollup.Actor;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidatePerson {
    public void validate(@RequestBody PersonRequest request, Out<PersonRequest> body, Out<Actor> actor)
            throws InvalidSheetRequestException {
        PersonRequest checked = PersonRequest.checked(request);
        actor.set(new Actor(checked.user()));
        body.set(checked);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadPerson {
    public void load(@PathVariable("sheetId") String sheetId, @PathVariable("personId") long personId,
            People people, Out<Person> personOut) throws PersonNotFoundException {
        Person person = people.find(sheetId, personId);
        if (person == null) throw new PersonNotFoundException(personId);
        personOut.set(person);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.sheet.InvalidSheetRequestException;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;

/** Changes the person's name and records the form's grade from its from-date (blank: the sheet's
 *  today), keeping the grades already recorded — except that a save leaving the grade as the row
 *  showed it (the one in force on the sheet's today), with the from-date blank, records none.
 *  The person's own terms become the form's (blank: none). */
public class ApplyPerson {
    public void apply(@Val PersonRequest request, @Val Person person, People people, Sheets sheets)
            throws InvalidSheetRequestException, PersonConflictException {
        if (request.version() != null && request.version() != person.getVersion()) {
            throw new PersonConflictException(PersonResponse.from(person));
        }
        if (people.nameTaken(person.getSheetId(), request.name(), person.getId())) {
            throw new InvalidSheetRequestException("The name is already in use on this sheet");
        }
        person.setName(request.name());
        person.changeTerms(request.termsDays());
        var from = request.gradeFromDate();
        var today = sheets.today(person.getSheetId());
        person.setToday(today);
        if (from == null && request.grade().equals(person.getGrade())) return;
        person.recordGrade(request.grade(), from != null ? from : today);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;

public class SavePerson {
    public void save(@Val Person person, People people) throws PersonConflictException {
        // Saved over by someone else between this request's load and its save: refused as a conflict.
        if (!people.save(person)) {
            Person current = people.find(person.getSheetId(), person.getId());
            throw new PersonConflictException(PersonResponse.from(current != null ? current : person));
        }
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;

/** Runs after the person is saved, so a refused edit writes no audit line. */
public class RecordPersonEdited {
    public void record(@Val PersonRequest request, @Val Person person, Audit audit) {
        audit.record("PERSON_EDITED sheet=" + person.getSheetId() + " by=" + request.user()
                + " name=" + person.getName() + " grade=" + person.getGrade()
                + (person.isTermsChanged() ? " terms=" + (person.getTerms() != null ? person.getTerms() : "") : ""));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithPerson {
    public void respond(@Val Person person, ObjectResponse<PersonResponse> response) {
        response.send(PersonResponse.from(person));
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.Set;
import net.officefloor.hq.app.sheet.InvalidSheetRequestException;

/** Body of a person add or edit: the name, the grade (A, B or C), who makes the change and, for an
 *  edit, the version of the person the editor loaded (null: no check), and the date the grade is
 *  in force from (yyyy-mm-dd; blank or null for the sheet's today), and the person's own terms in days
 *  (blank or null for none). */
public record PersonRequest(String name, String grade, String user, Integer version, String gradeFrom, String terms) {

    public PersonRequest(String name, String grade, String user, Integer version) {
        this(name, grade, user, version, null, null);
    }

    /** The terms given, or null when they were left blank. */
    public Integer termsDays() {
        return terms == null || terms.isBlank() ? null : Integer.valueOf(terms.trim());
    }

    /** The from-date given, or null when it was left blank. */
    public LocalDate gradeFromDate() {
        return gradeFrom == null || gradeFrom.isBlank() ? null : LocalDate.parse(gradeFrom.trim());
    }

    private static final Set<String> GRADES = Set.of("A", "B", "C");

    /** The request as the person rules accept it, or refused. */
    public static PersonRequest checked(PersonRequest request) throws InvalidSheetRequestException {
        if (request == null || request.name() == null || request.name().isBlank()) {
            throw new InvalidSheetRequestException("A name is required");
        }
        if (request.grade() == null || !GRADES.contains(request.grade())) {
            throw new InvalidSheetRequestException("The grade must be A, B or C");
        }
        String from = request.gradeFrom() == null ? "" : request.gradeFrom().trim();
        if (!from.isEmpty()) {
            try {
                LocalDate.parse(from);
            } catch (DateTimeParseException e) {
                throw new InvalidSheetRequestException("Not a date (yyyy-mm-dd): " + from);
            }
        }
        String terms = request.terms() == null ? "" : request.terms().trim();
        if (!terms.isEmpty() && !terms.matches("\\d{1,4}")) {
            throw new InvalidSheetRequestException("Terms must be a whole number of days: " + terms);
        }
        // Names are kept without the spaces around them.
        return new PersonRequest(request.name().trim(), request.grade(), request.user(), request.version(), from, terms);
    }
}

