package net.officefloor.hq.app.claim;

import java.util.LinkedHashSet;
import net.officefloor.hq.app.sheet.InvalidSheetRequestException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateBulkSettle {
    public void validate(@RequestBody BulkSettleRequest request, Out<BulkSettle> body) throws InvalidSheetRequestException {
        if (request == null || request.claimIds() == null || request.claimIds().isEmpty()) {
            throw new InvalidSheetRequestException("Select the claims to settle");
        }
        body.set(new BulkSettle(new LinkedHashSet<>(request.claimIds()), request.user()));
    }
}
package net.officefloor.hq.app.claim;

import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.ClosedPeriods;
import net.officefloor.hq.app.period.PeriodClosedException;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.Watches;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.Snapshot;
import net.officefloor.hq.app.settings.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Settles each selected claim that can be settled, in list order (people in list order, each
 *  person's newest claim first), by the signed-in user. Each is settled as a single settle would
 *  be — its own audit line, then the figures it moved; one that goes PENDING counts as settled. One
 *  that cannot be settled (or is not on the sheet) is left as it is and counted as refused. */
public class SettleClaims {
    public void settle(@PathVariable("sheetId") String sheetId, @Val BulkSettle bulk, Claims claims, People people,
            ClaimNumbers numbers, Figures figures, ClosedPeriods closedPeriods, Settings settings, Rollup rollup,
            ClaimLog log, Sheets sheets, Watches watches, Audit audit, Out<BulkSettleResult> result) {
        ClaimStatusChange change = new ClaimStatusChange(ClaimAction.SETTLE, bulk.user());
        ApplyClaimStatus apply = new ApplyClaimStatus();
        RecordClaimStatusChanged record = new RecordClaimStatusChanged();
        List<Claim> all = claims.onSheet(sheetId);
        int settled = 0;
        for (Person person : people.onSheet(sheetId)) {
            for (Claim listed : all) {
                if (listed.getPersonId() != person.getId() || !bulk.claimIds().contains(listed.getId())) continue;
                Claim claim = claims.find(sheetId, listed.getId());
                Snapshot before = rollup.snapshot(sheetId);
                try {
                    apply.apply(change, claim, numbers, people, figures, closedPeriods, settings, log, sheets);
                } catch (ClaimStatusRefusedException | PeriodClosedException e) {
                    continue;
                }
                claims.save(claim);
                record.record(change, claim, people, log, watches, audit);
                rollup.record(sheetId, before, bulk.user());
                settled++;
            }
        }
        result.set(new BulkSettleResult(settled, bulk.claimIds().size() - settled));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithBulkSettle {
    public void respond(@Val BulkSettleResult result, ObjectResponse<BulkSettleResult> response) {
        response.send(result);
    }
}
package net.officefloor.hq.app.claim;

import java.util.List;

/** Body of a bulk settle: the selected claims' ids and who settles them. */
public record BulkSettleRequest(List<Long> claimIds, String user) {
}
package net.officefloor.hq.app.claim;

/** How many of the selected claims a bulk settle settled (a claim gone PENDING counts), and how many it refused. */
public record BulkSettleResult(int settled, int refused) {
}
package net.officefloor.hq.app.rollup;

/** Who makes a change, published by the change's validating step for the steps after it. */
public record Actor(String user) {
}
package net.officefloor.hq.app.rollup;

import net.officefloor.plugin.variable.Val;

/** Runs after the change's own audit lines: audits the figures it moved. */
public class RecordRollup {
    public void record(@Val RollupBefore before, @Val Actor actor, Rollup rollup) {
        rollup.record(before.sheetId(), before.snapshot(), actor.user());
    }
}
package net.officefloor.hq.app.rollup;

/** The sheet's figures as they were before the change. */
public record RollupBefore(String sheetId, Snapshot snapshot) {
}
package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.Claims;
import net.officefloor.hq.app.claim.Figures;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.settings.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import org.springframework.stereotype.Service;

/**
 * The figures the screen shows — each person's claimed and due-total, the sheet's claimed-total and
 * due-total, and each one's overdue-total and the sheet's — worked out as the screen does, so a change can audit the ones it moved: one ROLLUP
 * line per person whose figures changed (a new person counts as changed), then a TOTALS line when
 * the sheet's totals changed.
 */
@Service
public class Rollup {

    private static final BigDecimal ZERO = BigDecimal.ZERO.setScale(2);

    private final People people;
    private final Claims claims;
    private final Figures figures;
    private final Rates rates;
    private final Sheets sheets;
    private final Audit audit;
    private final Settings settings;

    public Rollup(People people, Claims claims, Figures figures, Rates rates, Sheets sheets, Audit audit, Settings settings) {
        this.people = people;
        this.claims = claims;
        this.figures = figures;
        this.rates = rates;
        this.sheets = sheets;
        this.audit = audit;
        this.settings = settings;
    }

    /** The sheet's figures now. A person's due-total is the sum of their counting claims' figures (a
     *  person's OPEN claims dated within a hold of theirs, or any once today reaches their retirement
     *  date, do not count, unless a statement binds them),
     *  n/a when there is no rate today and none has a figure, at most the sheet's cap (n/a is not
     *  capped); the sheet's skips the n/a ones, and its due and overdue totals leave out the single
     *  highest and lowest person's figure when three or more have one. */
    public Snapshot snapshot(String sheetId) {
        LocalDate today = sheets.today(sheetId);
        List<Claim> all = claims.onSheet(sheetId);
        Map<Long, Snapshot.PersonFigures> figuresOf = new LinkedHashMap<>();
        BigDecimal claimedTotal = ZERO;
        List<BigDecimal> dues = new ArrayList<>();
        List<BigDecimal> overdues = new ArrayList<>();
        for (Person person : people.onSheet(sheetId)) {
            BigDecimal claimed = ZERO;
            BigDecimal due = ZERO;
            BigDecimal overdue = ZERO;
            boolean any = false;
            for (Claim claim : all) {
                if (claim.getPersonId() != person.getId() || !person.counts(claim)) continue;
                claimed = claimed.add(claim.getAmount());
                BigDecimal figure = figures.due(claim, person.gradeOn(claim.getDate()));
                if (figure != null) {
                    due = due.add(figure);
                    any = true;
                    if (claim.getStatus().isOpen() && !claim.isDeferred() && today != null && claim.getDueBy().isBefore(today)) {
                        overdue = overdue.add(figure);
                    }
                }
            }
            if (!any && rates.pct(sheetId, person.gradeOn(today), today) == null) due = null;
            due = settings.capped(sheetId, due);
            figuresOf.put(person.getId(), new Snapshot.PersonFigures(person.getName(), claimed, due, overdue));
            claimedTotal = claimedTotal.add(claimed);
            if (due != null) dues.add(due);
            overdues.add(overdue);
        }
        return new Snapshot(figuresOf, claimedTotal, trimmed(dues), trimmed(overdues));
    }

    /** The figures added up, leaving out the single highest and lowest when there are three or more. */
    private static BigDecimal trimmed(List<BigDecimal> figures) {
        List<BigDecimal> sorted = new ArrayList<>(figures);
        sorted.sort(BigDecimal::compareTo);
        if (sorted.size() >= 3) sorted = sorted.subList(1, sorted.size() - 1);
        return sorted.stream().reduce(ZERO, BigDecimal::add);
    }

    /** Audit the figures that moved between `before` and the sheet now. */
    public void record(String sheetId, Snapshot before, String user) {
        Snapshot after = snapshot(sheetId);
        String prefix = " sheet=" + sheetId + " by=" + user;
        after.people().forEach((id, now) -> {
            Snapshot.PersonFigures was = before.people().get(id);
            if (was != null && same(was.claimed(), now.claimed()) && same(was.dueTotal(), now.dueTotal())
