import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { claimsKey } from '../claims/useClaims';
import { useSelectedClaims } from './useSelectedClaims';

/**
 * Open the ticked claims together. Each that can be opened is opened and numbered in list order
 * (people in list order, each person's newest claim first); each that cannot is left as it is.
 * Shows how many were opened and how many refused; the counts go while the next press runs.
 */
function BulkOpen({ user, sheet }: { user: string; sheet: string }) {
  const queryClient = useQueryClient();
  const [selected, setSelected] = useSelectedClaims();
  const bulk = useMutation({
    mutationFn: (claimIds: number[]) =>
      postJson<{ opened: number; refused: number }>(`/api/sheets/${encodeURIComponent(sheet)}/bulk-open`, { claimIds, user }),
    onSuccess: () => setSelected([]),
    onSettled: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheet) }),
  });
  return (
    <section data-testid="bulk-open-panel">
      <button
        type="button"
        data-testid="bulk-open"
        disabled={bulk.isPending}
        onClick={() => {
          bulk.reset();
          bulk.mutate(selected);
        }}
      >
        Open selected ({selected.length})
      </button>
      {bulk.isSuccess && (
        <span>
          {' '}
          Opened <strong data-testid="bulk-opened">{bulk.data.opened}</strong>, refused{' '}
          <strong data-testid="bulk-refused">{bulk.data.refused}</strong>
        </span>
      )}
      {bulk.isError && (
        <span data-testid="bulk-open-error" role="alert">
          {' '}
          {selected.length === 0 ? 'Select the claims to open.' : 'Could not open the selected claims.'}
        </span>
      )}
    </section>
  );
}

export const contribution = SheetPanels.fill({ order: 15, Component: BulkOpen });
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { claimsKey } from '../claims/useClaims';
import { useSelectedClaims } from './useSelectedClaims';

/**
 * Settle the ticked claims together, by the signed-in user. Each that can be settled is settled
 * (or goes PENDING) in list order (people in list order, each person's newest claim first); each
 * that cannot is left as it is. Shows how many were settled and how many refused; the counts go
 * while the next press runs.
 */
function BulkSettle({ user, sheet }: { user: string; sheet: string }) {
  const queryClient = useQueryClient();
  const [selected, setSelected] = useSelectedClaims();
  const bulk = useMutation({
    mutationFn: (claimIds: number[]) =>
      postJson<{ settled: number; refused: number }>(`/api/sheets/${encodeURIComponent(sheet)}/bulk-settle`, { claimIds, user }),
    onSuccess: () => setSelected([]),
    onSettled: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheet) }),
  });
  return (
    <section data-testid="bulk-settle-panel">
      <button
        type="button"
        data-testid="bulk-settle"
        disabled={bulk.isPending}
        onClick={() => {
          bulk.reset();
          bulk.mutate(selected);
        }}
      >
        Settle selected ({selected.length})
      </button>
      {bulk.isSuccess && (
        <span>
          {' '}
          Settled <strong data-testid="bulk-settled">{bulk.data.settled}</strong>, refused{' '}
          <strong data-testid="bulk-settle-refused">{bulk.data.refused}</strong>
        </span>
      )}
      {bulk.isError && (
        <span data-testid="bulk-settle-error" role="alert">
          {' '}
          {selected.length === 0 ? 'Select the claims to settle.' : 'Could not settle the selected claims.'}
        </span>
      )}
    </section>
  );
}

export const contribution = SheetPanels.fill({ order: 16, Component: BulkSettle });
import { useSearchParam } from '../../url/useSearchParam';

const asIds = (raw: unknown): number[] =>
  Array.isArray(raw) ? raw.map(Number).filter((n) => Number.isInteger(n)) : [];

/** The claims ticked for a bulk action, by id. Kept in the URL, like any selection. */
export function useSelectedClaims(): [number[], (ids: number[]) => void] {
  const [ids, set] = useSearchParam('selected', asIds);
  return [ids, (next) => set(next.length === 0 ? undefined : next)];
}
import { defineSlot } from '../Slot';

/**
 * The shell's nav bar. Every page contributes its own link — the shell never lists the pages.
 * A nav link carries `data-testid="nav-<section>"` (the test contract; CLAUDE.md).
 */
export const AppNav = defineSlot('app.nav');
import { defineSlot } from '../Slot';
import type { Person } from '../../features/people/usePeople';

/** Extra column headers of the people list, one `<th>` per contribution. */
export const PersonColumns = defineSlot<{ user: string; sheet: string }>('person.columns');

/**
 * Extra cells of a person's row, one `<td>` per contribution, in the same order as their
 * PersonColumns headers. Everything kept per person (claims, ...) shows here, inside the row.
 */
export const PersonCells = defineSlot<{ user: string; sheet: string; person: Person }>('person.cells');
import { defineSlot } from '../Slot';

/**
 * The active sheet's content on the home screen. Rendered only once someone is signed in and a
 * sheet is loaded; everything kept per sheet contributes a panel here, keyed by `sheet`.
 */
export const SheetPanels = defineSlot<{ user: string; sheet: string }>('sheet.panels');
import type { ComponentType } from 'react';

// The contribution store. It imports NOTHING — that is deliberate: discovery (slots/discover.ts)
// pulls in every feature's contribution file, and those files reach a slot definition, which
// reaches defineSlot, which reaches this file. Keeping the arrows one-way (discover -> features ->
// defs -> Slot -> registry) is what stops the module graph forming a cycle.

export type Registered = {
  slot: string;
  order: number;
  /** Source file — the React key and the deterministic tie-break for equal `order`. */
  from: string;
  Component: ComponentType<never>;
};

const contributions: Registered[] = [];

/** Called once per contribution at startup, by slots/discover.ts. */
export function register(entry: Registered): void {
